"""P5 — Analyse par Marque"""import streamlit as stimport plotly.graph_objects as goimport plotly.express as pxfrom config import C, apply_themefrom components.kpi_cards import kpi_row, section_title, page_headerfrom data.loader import load_brandsdef render():    page_header("Analyse par Marque",                "Concentration du marché · satisfaction · flux internationaux", "⌚")    df = load_brands()    kpi_row([        {"title":"Rolex — leader absolu","value":"26 473","subtitle":"15% du marché","color":"orange","icon":"🥇"},        {"title":"Omega — 2e mondiale","value":"21 476","subtitle":"12.2% du marché","color":"blue","icon":"🥈"},        {"title":"Top 2 = 27% du marché","value":"27%","subtitle":"Forte concentration","color":"purple","icon":"📊"},        {"title":"Seiko — taux intl. max","value":"82%","subtitle":"Marque la + internationale","color":"teal","icon":"✈️"},    ])    section_title("Concentration du marché — Treemap", "🌳")    fig_tree = px.treemap(        df, path=["Marque"], values="Nb transactions",        color="% Ventes intl.",        color_continuous_scale=["#1A3A6E","#1A73E8","#34A853","#FBBC04"],        range_color=[60, 85],        custom_data=["Note globale","% Ventes intl."],    )    fig_tree.update_traces(        texttemplate="<b>%{label}</b><br>%{value:,} tx<br>%{customdata[1]:.1f}% intl.",        textfont=dict(size=12, color="#FFFFFF"),        hovertemplate=(            "<b>%{label}</b><br>Volume : <b>%{value:,}</b><br>"            "Satisfaction : <b>%{customdata[0]:.3f}/5</b><br>"            "% International : <b>%{customdata[1]:.1f}%</b><extra></extra>"),        marker=dict(pad=dict(t=22, l=6, r=6, b=6)),    )    apply_theme(fig_tree, "Volume par marque · couleur = % ventes internationales")    fig_tree.update_layout(height=400)    fig_tree.update_coloraxes(        colorbar=dict(title=dict(text="% intl.", font=dict(color=C["muted"])),                      tickfont=dict(color=C["muted"])))    st.plotly_chart(fig_tree, use_container_width=True)    section_title("Volume · Satisfaction · Internationalisation", "🫧")    fig_bub = go.Figure(go.Scatter(        x=df["Nb transactions"], y=df["Note globale"],        mode="markers+text",        marker=dict(            size=df["% Ventes intl."] * 1.0,            sizemode="diameter", sizeref=1.5,            color=df["% Ventes intl."],            colorscale=[[0,C["blue"]],[0.5,C["teal"]],[1,C["orange"]]],            cmin=60, cmax=85, showscale=True,            colorbar=dict(title=dict(text="% intl.", font=dict(color=C["muted"])),                          tickfont=dict(color=C["muted"])),            line=dict(color=C["bg"], width=1.5), opacity=0.85),        text=df["Marque"],        textposition="top center", textfont=dict(size=11, color=C["text"]),        hovertemplate=(            "<b>%{text}</b><br>Volume : <b>%{x:,}</b><br>"            "Satisfaction : <b>%{y:.3f}/5</b><br>"            "% International : <b>%{marker.color:.1f}%</b><extra></extra>"),    ))    fig_bub.add_hline(y=df["Note globale"].mean(), line_dash="dash",                      line_color=C["border"], opacity=0.5,                      annotation_text=f"Sat. moy. {df['Note globale'].mean():.3f}",                      annotation_font_color=C["muted"])    apply_theme(fig_bub, "Axe X : volume · Y : satisfaction · Taille & couleur : % international")    fig_bub.update_layout(height=420, showlegend=False,                          xaxis=dict(title="Nombre de transactions", type="log"),                          yaxis=dict(title="Note globale / 5"))    st.plotly_chart(fig_bub, use_container_width=True)    col1, col2 = st.columns(2)    df_s = df.sort_values("Note globale", ascending=True)    df_i = df.sort_values("% Ventes intl.", ascending=True)    with col1:        section_title("Satisfaction par marque")        fig_s = go.Figure(go.Bar(            y=df_s["Marque"], x=df_s["Note globale"], orientation="h",            marker=dict(color=df_s["Note globale"], colorscale="RdYlGn",                        cmin=4.77, cmax=4.86, line=dict(color=C["bg"], width=0.5)),            text=[f" {v:.3f}" for v in df_s["Note globale"]],            textposition="outside", textfont=dict(color=C["text"], size=10),            hovertemplate="<b>%{y}</b><br>%{x:.3f}/5<extra></extra>",        ))        apply_theme(fig_s, "")        fig_s.update_layout(height=400, margin=dict(r=60))        fig_s.update_xaxes(range=[4.75, 4.87])        st.plotly_chart(fig_s, use_container_width=True)    with col2:        section_title("% international par marque")        fig_i = go.Figure(go.Bar(            y=df_i["Marque"], x=df_i["% Ventes intl."], orientation="h",            marker=dict(color=df_i["% Ventes intl."],                        colorscale=[[0,C["card2"]],[1,C["teal"]]],                        line=dict(color=C["bg"], width=0.5)),            text=[f" {v:.1f}%" for v in df_i["% Ventes intl."]],            textposition="outside", textfont=dict(color=C["text"], size=10),            hovertemplate="<b>%{y}</b><br>%{x:.1f}%<extra></extra>",        ))        apply_theme(fig_i, "")        fig_i.update_layout(height=400, margin=dict(r=60))        st.plotly_chart(fig_i, use_container_width=True)